import Link from "next/link";

const Header = () => {
  return (
    <div className="bg-blue-900 py-6">
      <div className="container mx-auto flex justify-between">
        <span className="text-white text-3xl font-bold">Booking</span>
        <span className="flex justify-between gap-3">
          <Link href="/login" className="flex items-center bg-white px-4 font-bold text-blue-900">Login</Link>
          <Link href="/register" className="flex items-center bg-white px-4 font-bold text-blue-900">Register</Link>
        </span>

      </div>
    </div>
  );
}

export default Header;
